  [0.00, new THREE.Color(0x8fc0ea)],
  [0.30, new THREE.Color(0xa9d4f5)],
  [0.60, new THREE.Color(0xefa6c8)],
  [0.85, new THREE.Color(0x9c6fd2)],
  [1.00, new THREE.Color(0x7f5bc0)]
