const _c = new THREE.Color();
function ramp(t) {
  t = Math.max(0, Math.min(1, t));
  for (let s = 0; s < STOPS.length - 1; s++) {
    const [t0, c0] = STOPS[s], [t1, c1] = STOPS[s + 1];
    if (t <= t1) { _c.copy(c0).lerp(c1, (t - t0) / (t1 - t0)); return _c; }
  }
  return _c.copy(STOPS[STOPS.length - 1][1]);
