      `r₊ = ${r1.toFixed(2)},&nbsp; r₋ = ${r2.toFixed(2)}<br>` +
      `V₊ = ${vp.toFixed(2)},&nbsp; V₋ = ${vm.toFixed(2)}<br>` +
