      sPos[3 * k] = x; sPos[3 * k + 1] = v; sPos[3 * k + 2] = z;
      const col = ramp(Math.abs(v) / VCLAMP);
      sCol[3 * k] = col.r; sCol[3 * k + 1] = col.g; sCol[3 * k + 2] = col.b;
    }
  }
  surfGeom.attributes.position.needsUpdate = true;
  surfGeom.attributes.color.needsUpdate = true;
  surfGeom.computeVertexNormals();
  surfGeom.computeBoundingBox();
  surfGeom.computeBoundingSphere();
}

/* ── contour levels: finely spaced near V = 0 (big loops on the sheet),
      widening toward the clipped extremes (tight rings on the flanks) ─── */
const POSL = [0.035, 0.075, 0.125, 0.19, 0.27, 0.37, 0.49, 0.63, 0.79, 0.97, 1.16, 1.36];
const LEVELS = [];
for (let i = POSL.length - 1; i >= 0; i--) LEVELS.push(-POSL[i]);
for (const L of POSL) LEVELS.push(L);

const solidGeom = new THREE.BufferGeometry();
solidGeom.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0, 0, 0, 0], 3));
const contoursSolid = new THREE.LineSegments(
  solidGeom, new THREE.LineBasicMaterial({ color: 0x1a1a28, transparent: true, opacity: 0.9 })
);
const dashGeom = new THREE.BufferGeometry();
dashGeom.setAttribute('position', new THREE.Float32BufferAttribute([0, 0, 0, 0, 0, 0], 3));
const contoursDashed = new THREE.LineSegments(
  dashGeom, new THREE.LineDashedMaterial({
    color: 0x1a1a28, transparent: true, opacity: 0.88, dashSize: 0.085, gapSize: 0.06
  })
);
contoursDashed.computeLineDistances();
scene.add(contoursSolid, contoursDashed);

function updateContours() {
  const solid = [], dashed = [];
  const M = Math.floor((N - 1) / CS);
  const val = (ci, cj) => Vg[(cj * CS) * N + ci * CS];
  const X = ci => gx(ci * CS), Z = cj => gz(cj * CS);
  for (const L of LEVELS) {
    const out = L < 0 ? dashed : solid;
    for (let cj = 0; cj < M; cj++) {
      for (let ci = 0; ci < M; ci++) {
        const v00 = val(ci, cj), v10 = val(ci + 1, cj),
              v11 = val(ci + 1, cj + 1), v01 = val(ci, cj + 1);
        const mn = Math.min(v00, v10, v11, v01), mx = Math.max(v00, v10, v11, v01);
        if (L < mn || L > mx) continue;
        const x0 = X(ci), x1 = X(ci + 1), z0 = Z(cj), z1 = Z(cj + 1);
        const P = [];
        if ((v00 < L) !== (v10 < L)) { const t = (L - v00) / (v10 - v00); P.push([x0 + t * (x1 - x0), z0]); } else P.push(null);
        if ((v10 < L) !== (v11 < L)) { const t = (L - v10) / (v11 - v10); P.push([x1, z0 + t * (z1 - z0)]); } else P.push(null);
        if ((v01 < L) !== (v11 < L)) { const t = (L - v01) / (v11 - v01); P.push([x0 + t * (x1 - x0), z1]); } else P.push(null);
        if ((v00 < L) !== (v01 < L)) { const t = (L - v00) / (v01 - v00); P.push([x0, z0 + t * (z1 - z0)]); } else P.push(null);
        const hit = P.filter(Boolean);
        if (hit.length === 2) {
          out.push(hit[0][0], L, hit[0][1], hit[1][0], L, hit[1][1]);
        } else if (hit.length === 4) {
          const ctr = (v00 + v10 + v11 + v01) / 4;
          const pairs = ctr >= L ? [[0, 1], [2, 3]] : [[0, 3], [1, 2]];
          for (const [a, b] of pairs) out.push(P[a][0], L, P[a][1], P[b][0], L, P[b][1]);
        }
      }
    }
  }
  solidGeom.setAttribute('position',
    new THREE.Float32BufferAttribute(solid.length ? solid : [0, 0, 0, 0, 0, 0], 3));
  solidGeom.computeBoundingSphere();
  dashGeom.setAttribute('position',
    new THREE.Float32BufferAttribute(dashed.length ? dashed : [0, 0, 0, 0, 0, 0], 3));
  dashGeom.computeBoundingSphere();
  contoursDashed.computeLineDistances();
}

/* ── faint straight V = 0 trace along the depth direction ─────────────── */
const zeroTrace = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0.004, -ZR), new THREE.Vector3(0, 0.004, ZR)]),
  new THREE.LineBasicMaterial({ color: 0x6e7ea0 })
);
scene.add(zeroTrace);

/* ── label leader lines (drawn over the surface so both tips read) ────── */
function makeLeader() {
  const g = new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(), new THREE.Vector3()]);
  const m = new THREE.LineBasicMaterial({ color: 0x777777, depthTest: false, transparent: true, opacity: 0.9 });
  const l = new THREE.Line(g, m);
  l.renderOrder = 5;
  scene.add(l);
  return l;
}
const leadPlus = makeLeader(), leadMinus = makeLeader();
function setLeader(line, x, y0, y1) {
  const p = line.geometry.attributes.position;
  p.setXYZ(0, x, y0, 0); p.setXYZ(1, x, y1, 0);
  p.needsUpdate = true;
  line.geometry.computeBoundingSphere();
}

/* ── probe marker ─────────────────────────────────────────────────────── */
const probeDot = new THREE.Mesh(new THREE.SphereGeometry(0.05, 16, 12),
  new THREE.MeshBasicMaterial({ color: 0xff8800 }));
probeDot.visible = false;
scene.add(probeDot);

/* ── first build + camera ─────────────────────────────────────────────── */
updateSurface();
updateContours();
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: HF });
document.getElementById('btnReset').style.display = '';

/* ── labels ───────────────────────────────────────────────────────────── */
const labPlus = addLabel('+<i>q</i>', new THREE.Vector3(sep / 2, VCLAMP + 0.3, 0),
  { color: '#5f2a9c', fontSize: '15px', bold: true, offset: [0, -9] });
const labMinus = addLabel('&minus;<i>q</i>', new THREE.Vector3(-sep / 2, -VCLAMP - 0.3, 0),
  { color: '#1d4e9b', fontSize: '15px', bold: true, offset: [0, 11] });
const labZero = addLabel('<i>V</i> = 0', new THREE.Vector3(0, 0.03, ZR + 0.3),
  { color: '#5a6a8a', fontSize: '13px', offset: [0, 10] });

function updateLabels() {
  const vP = potential(sep / 2, 0) * flatten;
  const vM = potential(-sep / 2, 0) * flatten;
  const up = Math.min(vP + 0.32, BOXH - 0.06);
  const dn = Math.max(vM - 0.32, -BOXH + 0.06);
  setLeader(leadPlus, sep / 2, vP, up);
  setLeader(leadMinus, -sep / 2, vM, dn);
  labPlus.pos.set(sep / 2, up, 0);
  labMinus.pos.set(-sep / 2, dn, 0);
  labZero.pos.set(0, 0.03 * flatten, ZR + 0.32);
}

function rebuild() {
  updateSurface();
  updateContours();
  updateLabels();
}

/* ── UI wiring ────────────────────────────────────────────────────────── */
const sBal = document.getElementById('sBal');
const sSep = document.getElementById('sSep');
const valBal = document.getElementById('valBal');
const valSep = document.getElementById('valSep');
const probeBox = document.getElementById('probe');

sBal.addEventListener('input', () => {
  bal = parseFloat(sBal.value);
  valBal.textContent = bal.toFixed(2);
  rebuild();
});
sSep.addEventListener('input', () => {
  sep = parseFloat(sSep.value);
  valSep.textContent = sep.toFixed(1);
  rebuild();
});

const btnSurf = document.getElementById('mSurf');
const btnBoth = document.getElementById('mBoth');
const btnTop = document.getElementById('mTop');

function setMode(m) {
  mode = m;
  btnSurf.classList.toggle('active', m === 'surf');
  btnBoth.classList.toggle('active', m === 'both');
  btnTop.classList.toggle('active', m === 'top');
  contoursSolid.visible = (m !== 'surf');
  contoursDashed.visible = (m !== 'surf');
  if (m === 'top') { flattenTarget = 0.001; elevTarget = 89.5; }
  else { flattenTarget = 1; elevTarget = 35.264; }
  camTween = true;
}
btnSurf.addEventListener('click', () => setMode('surf'));
btnBoth.addEventListener('click', () => setMode('both'));
btnTop.addEventListener('click', () => setMode('top'));
setMode('both');

/* ── guided tour ──────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'Equal and opposite charges',
    n: 'A single smooth surface: potential rises into a steep peak over the positive sphere on the right and drops into an identical well over the negative sphere on the left, flattening to zero far away.',
    s: { bal: -1, sep: 2.5, mode: 'surf' } },
  { t: 'Contours read the slope',
    n: 'Level curves crowd on the steep flanks and spread into wide loops on the flat sheet — close contours mark a strong field, wide ones a weak field. Dashed loops lie below V = 0.',
    s: { bal: -1, sep: 2.5, mode: 'both' } },
  { t: 'Flatten to the contour map',
    n: 'Looking straight down, the relief collapses into the familiar equipotential map: nested loops around each sphere and a straight zero-potential line down the middle.',
    s: { bal: -1, sep: 2.5, mode: 'top' } },
  { t: 'Unbalance the charges',
    n: 'Weakening the negative charge shrinks its well and lifts the far-field sheet above zero — the net charge no longer cancels, and the zero line bends around the smaller charge.',
    s: { bal: -0.4, sep: 2.5, mode: 'both' } },
  { t: 'Bring them together',
    n: 'Sliding the spheres close, peak and well overlap and largely cancel, leaving a compact dipole whose potential collapses quickly.',
    s: { bal: -1, sep: 1.0, mode: 'both' } },
  { t: 'Pull them apart',
    n: 'Widely separated, each funnel is essentially an isolated point-charge potential with its own circular contours, and the region between goes nearly flat.',
    s: { bal: -1, sep: 4.0, mode: 'both' } }
];
let step = 0;
function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const S = STEPS[step];
  bal = S.s.bal; sep = S.s.sep;
  sBal.value = bal; sSep.value = sep;
  valBal.textContent = bal.toFixed(2);
  valSep.textContent = sep.toFixed(1);
  setMode(S.s.mode);
  rebuild();
  document.getElementById('stepTitle').textContent = S.t;
  document.getElementById('stepText').textContent = S.n;
  document.getElementById('stepNum').textContent = (step + 1) + ' / ' + STEPS.length;
}
document.getElementById('bPrev').addEventListener('click', () => goToStep(step - 1));
document.getElementById('bNext').addEventListener('click', () => goToStep(step + 1));
goToStep(1);

/* ── hover probe + click explanations on the two funnels ──────────────── */
const rc = new THREE.Raycaster();
const pv = new THREE.Vector2();
function hitSurface(e) {
  const r = canvas.getBoundingClientRect();
  pv.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  pv.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  rc.setFromCamera(pv, camera);
  const hits = rc.intersectObject(surface, false);
  return hits.length ? hits[0].point : null;
}
canvas.addEventListener('pointermove', (e) => {
  const p = hitSurface(e);
  if (p) {
    const x = p.x, z = p.z;
    const r1 = Math.max(Math.hypot(x - sep / 2, z), A);
    const r2 = Math.max(Math.hypot(x + sep / 2, z), A);
    const vp = K / r1, vm = K * bal / r2;
    const v = Math.max(-VCLAMP, Math.min(VCLAMP, vp + vm));
    probeDot.position.set(x, v * flatten, z);
    probeDot.visible = true;
    showTooltip(`V = ${v.toFixed(2)}  (+q: ${vp.toFixed(2)},  q₋: ${vm.toFixed(2)})`, e);
    probeBox.innerHTML =
      `x = ${x.toFixed(2)},&nbsp; y = ${z.toFixed(2)}<br>` +
      `r₊ = ${r1.toFixed(2)},&nbsp; r₋ = ${r2.toFixed(2)}<br>` +
      `V₊ = ${vp.toFixed(2)},&nbsp; V₋ = ${vm.toFixed(2)}<br>` +
      `<b>V = V₊ + V₋ = ${v.toFixed(2)}</b>`;
  } else {
    probeDot.visible = false;
    hideTooltip();
  }
});
canvas.addEventListener('pointerleave', () => { probeDot.visible = false; });
canvas.addEventListener('click', (e) => {
  const p = hitSurface(e);
  if (!p) return;
  const dPlus = Math.hypot(p.x - sep / 2, p.z);
  const dMinus = Math.hypot(p.x + sep / 2, p.z);
  if (dPlus < 1.0) {
    showPopup('Positive sphere (+q)',
      'A conducting sphere of radius a = 0.32 carrying +q. Inside the sphere the potential is fixed at its surface value, so the peak is cut off by a flat circular cap instead of diverging as 1/r → ∞.');
  } else if (dMinus < 1.0) {
    showPopup('Negative sphere (q₋)',
      'The second sphere carries q₋ = (balance) × q₊. Potential is a signed scalar, so a negative charge digs a well exactly as deep as an equal positive charge is tall — truncated by the same flat floor at the sphere surface.');
  }
});

/* ── tween loop for flatten + camera elevation ────────────────────────── */
(function tick() {
  requestAnimationFrame(tick);
  let dirty = false;
  if (Math.abs(flatten - flattenTarget) > 1e-4) {
    flatten += (flattenTarget - flatten) * 0.12;
    dirty = true;
  } else if (flatten !== flattenTarget) { flatten = flattenTarget; dirty = true; }
  if (dirty) {
    const f = Math.max(0.0012, flatten);
    surface.scale.y = f;
    contoursSolid.scale.y = f;
    contoursDashed.scale.y = f;
    zeroTrace.scale.y = f;
    updateLabels();
  }
  if (camTween) {
    if (Math.abs(elev - elevTarget) > 0.05) {
      elev += (elevTarget - elev) * 0.12;
    } else {
      elev = elevTarget;
      camTween = false;
    }
    setCameraView({
      projection: 'orthographic', azimuthDeg: azim, elevationDeg: elev,
      rollDeg: 0, heightFraction: HF
    });
  }
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
