<div style="display:flex;gap:4px;flex-wrap:wrap">
  <button id="mSurf">Surface</button>
  <button id="mBoth" class="active">Surface + contours</button>
  <button id="mTop">Contour map</button>
</div>
<div style="color:#666;line-height:1.3;margin-top:2px">
  Equally spaced levels: solid above <i>V</i> = 0, dashed below. Crowded rings = steep surface = strong field.
</div>

<div style="margin-top:6px">Guided tour</div>
<div style="display:flex;gap:4px;align-items:center">
  <button id="bPrev">&#9664; Prev</button>
  <button id="bNext">Next &#9654;</button>
  <span id="stepNum" style="color:#666"></span>
</div>
